<template><div>
<header class="topbar"><div class="crumb">学习分析 / <b>答题记录</b></div><div class="search">⌕ <span>搜索会话…</span></div><div class="top-actions"><button class="btn ghost" @click="load">刷新</button><div class="avatar">AS</div></div></header>
<div class="content"><div class="page-title"><div><h1>答题记录</h1><p>查看每次学习会话和每道题的判题结果。</p></div><div class="quick-stats"><div class="stat"><span>会话</span><b>{{total}}</b></div></div></div>
<div class="panel" style="overflow:hidden"><div style="display:grid;grid-template-columns:1.2fr 90px 90px 1fr 120px;gap:10px;padding:11px 16px;background:#f8fafd;color:#7f8da0;font-size:11px;border-bottom:1px solid var(--line)"><span>开始时间</span><span>状态</span><span>进度</span><span>题目</span><span>操作</span></div><div v-for="s in items" :key="s.id" style="display:grid;grid-template-columns:1.2fr 90px 90px 1fr 120px;gap:10px;padding:13px 16px;border-bottom:1px solid #f0f4f9;align-items:center;font-size:13px"><span>{{s.createdAt}}</span><span class="pill" :class="s.status==='completed'?'green':'blue'">{{s.status}}</span><span>{{s.progress?.answered||0}} / {{s.questionCount||s.progress?.total||5}}</span><span class="muted">#{{s.id}}</span><button class="link" @click="open(s)">查看详情</button></div><div v-if="!items.length" class="empty"><b>暂无答题记录</b>电视端开启学习闯关后，会话会显示在这里。</div></div></div>
<div v-if="active" class="drawer-backdrop" @click.self="active=null"></div><aside v-if="active" class="drawer"><div class="drawer-head"><h2>会话详情</h2><button class="close" @click="active=null">×</button></div><div class="drawer-body"><div v-if="detail"><div class="meta"><div class="meta-item"><span>会话</span>{{detail.id}}</div><div class="meta-item"><span>状态</span>{{detail.status}}</div><div class="meta-item"><span>开始</span>{{detail.createdAt}}</div><div class="meta-item"><span>完成</span>{{detail.finishedAt||'—'}}</div></div><div v-for="a in detail.attempts" :key="a.attemptNo" style="border-bottom:1px solid #f0f4f9;padding:10px 0"><b style="font-size:13px">{{a.questionPrompt||('题目 #'+a.questionId)}}</b><div class="muted" style="font-size:12px;margin-top:3px">作答：{{a.transcript||a.selectedOption||'—'}} · 正确答案：{{a.questionAnswer||'—'}}</div><div style="margin-top:4px"><span class="pill" :class="a.correct?'green':'red'">{{a.correct?'正确':'错误'}}</span> <span class="faint" style="font-size:11px">{{a.judgeMethod}} · {{a.createdAt}}</span></div></div></div></div></aside>
<div v-if="toast" :key="toast" class="toast">{{toast}}</div></div>
</template>
<script setup>import{ref,onMounted}from'vue';import{api}from'../api';const items=ref([]),total=ref(0),active=ref(null),detail=ref(null),toast=ref('');async function load(){try{const d=await api('/api/v1/admin/records?limit=100');items.value=d.items||[];total.value=d.total??items.length}catch(e){toast.value=e.message}}async function open(s){active.value=s;detail.value=null;try{detail.value=await api('/api/v1/admin/records/'+s.id)}catch(e){toast.value=e.message}}onMounted(load)</script>
